--[=[
    @class Container

    * 容器为悟空框架的抽象概念.
    * 容器中容纳了单个玩家的所有游戏数据.
    * 通过配置, 容器实现了相关业务规则, 供框架调用.
]=]

local IHasPlugin = require(script.Parent.IHasPlugin)
local IHasPluginData = require(script.Parent.IHasPluginData)

local Container = {}

export type Type = typeof(Container) & IHasPlugin.Type & IHasPluginData.Type

--- @prop Id string
--- @within Container
--- 容器编号
Container.Id = ""

--- 获取原始配置表
function Container:getOriginConfig(): {} end

--- 获取容器路径
function Container:getPath() end

--[=[
    获取子节点列表
    @return {Container}: 返回子节点列表
]=]
function Container:getChildren(): { Type } end

--- 是否含有任意子节点
function Container:getHasChildren(): boolean end

--[=[
    尝试获取节点容器
    @param id string -- 节点编号
    @return bool -- 指定编号节点是否存在
    @return Container -- 该节点对应容器对象
]=]
function Container:TryGetChild(id: string): (boolean, Type) end

--[=[
    获取节点容器, 如果未找到,则报错
    @param id string -- 节点编号
    @return Container -- 该节点对应容器对象
]=]
function Container:GetChild(id: string): Type end

return Container
